package main

import (
	"fmt"
	"github.com/datreeio/datree/pkg/utils"
)

func main() {
	fmt.Println("=== Testing Examples Function ===\n")

	// Test 1: Empty string
	fmt.Println("Test 1: Empty string")
	empty := utils.Examples("")
	if empty == "" {
		fmt.Println("✓ PASS: Empty string returns empty string")
	} else {
		fmt.Printf("✗ FAIL: Expected empty string, got '%s'\n", empty)
	}

	// Test 2: Single line with leading/trailing whitespace
	fmt.Println("\nTest 2: Single line with whitespace")
	singleLine := utils.Examples("  datree test ./file.yaml  ")
	expected := "  datree test ./file.yaml"
	if singleLine == expected {
		fmt.Println("✓ PASS: Single line trimmed and indented correctly")
	} else {
		fmt.Printf("✗ FAIL: Expected '%s', got '%s'\n", expected, singleLine)
	}

	// Test 3: Multi-line with various indentation
	fmt.Println("\nTest 3: Multi-line examples")
	multiLine := utils.Examples(`
		# First example
		datree test ./kube/**/*.yaml

		# Second example
		datree publish ./policy.yaml`)

	lines := []string{
		"  # First example",
		"  datree test ./kube/**/*.yaml",
		"  ",
		"  # Second example",
		"  datree publish ./policy.yaml",
	}

	expectedMulti := ""
	for i, line := range lines {
		if i > 0 {
			expectedMulti += "\n"
		}
		expectedMulti += line
	}

	if multiLine == expectedMulti {
		fmt.Println("✓ PASS: Multi-line examples formatted correctly")
		fmt.Println("\nFormatted output:")
		fmt.Println(multiLine)
	} else {
		fmt.Printf("✗ FAIL: Multi-line formatting incorrect\nExpected:\n%s\n\nGot:\n%s\n", expectedMulti, multiLine)
	}

	// Test 4: Verify two-space indentation
	fmt.Println("\nTest 4: Two-space indentation")
	testIndent := utils.Examples("example")
	if len(testIndent) == 9 && testIndent[:2] == "  " {
		fmt.Println("✓ PASS: Correct two-space indentation")
	} else {
		fmt.Printf("✗ FAIL: Indentation incorrect. Got: '%s'\n", testIndent)
	}

	fmt.Println("\n=== All Tests Completed ===")
}
EOF
